        if (dynamic_cast<wxFileDialogBase*>(dialog) != nullptr || dynamic_cast<wxDirDialogBase*>(dialog) != nullptr) {
            std::cerr << "HARNESS DIALOG CLOSED picker answer=" << wxID_CANCEL << '\n';
            return wxID_CANCEL;
        }
        return wxID_NONE;
    }

private:
    void report(const char* kind, wxDialog& dialog)
    {
